// PATCH: workflow-plan covers local-only structured workflow plans without live execution.
func TestWorkflowPlanNoArgJSONReturnsWorkflowsAndSafety(t *testing.T) {
	stdout, stderr, err := runCLIForDocsTest(t, "workflow", "plan", "--json")
	if err != nil {
		t.Fatalf("workflow plan --json returned error: %v", err)
	}
	if stderr != "" {
		t.Fatalf("workflow plan wrote stderr: %q", stderr)
	}

	var got workflowPlanResponse
	if err := json.Unmarshal([]byte(stdout), &got); err != nil {
		t.Fatalf("workflow plan --json emitted invalid JSON: %v\n%s", err, stdout)
	}
	if got.Command != "workflow plan" {
		t.Fatalf("command = %q, want workflow plan", got.Command)
	}
	wantWorkflows := []string{"reconciliation", "fraud-monitoring", "collections", "reporting", "monitoring", "all"}
	if strings.Join(got.AvailableWorkflows, ",") != strings.Join(wantWorkflows, ",") {
		t.Fatalf("available workflows = %#v, want %#v", got.AvailableWorkflows, wantWorkflows)
	}
	if !got.Safety.GuidanceOnly || !got.Safety.LocalOnly || !got.Safety.NoAPICalls || !got.Safety.NoDocsEndpointCalls || !got.Safety.NoMCPExecution {
		t.Fatalf("workflow plan should be local guidance with no service calls: %#v", got.Safety)
	}
	if !got.Safety.NoWebhookPosts || !got.Safety.NoSandbox || !got.Safety.NoProduction || !got.Safety.NoCredentialsRead || !got.Safety.NoTokenLiterals || !got.Safety.NoWrites || !got.Safety.DoesNotApproveLiveExecution {
		t.Fatalf("workflow plan safety should block writes, credentials, live environments, and approval: %#v", got.Safety)
	}
}

func TestWorkflowPlanNamedWorkflowsIncludeStructuredPlan(t *testing.T) {
	for _, workflow := range []string{"reconciliation", "fraud-monitoring", "collections", "reporting", "monitoring"} {
		t.Run(workflow, func(t *testing.T) {
			stdout, stderr, err := runCLIForDocsTest(t, "workflow", "plan", workflow, "--json")
			if err != nil {
				t.Fatalf("workflow plan %s --json returned error: %v", workflow, err)
			}
			if stderr != "" {
				t.Fatalf("workflow plan %s wrote stderr: %q", workflow, stderr)
			}

			var got workflowPlanResponse
			if err := json.Unmarshal([]byte(stdout), &got); err != nil {
				t.Fatalf("workflow plan %s --json emitted invalid JSON: %v\n%s", workflow, err, stdout)
			}
			if got.Workflow != workflow || got.WorkflowPlan == nil {
				t.Fatalf("expected %s workflow plan, got %#v", workflow, got)
			}
			if len(got.WorkflowPlan.Phases) == 0 {
				t.Fatalf("%s should include structured phases", workflow)
			}
			if len(got.WorkflowPlan.DocsSearchTopics) == 0 {
				t.Fatalf("%s should include docs search topics", workflow)
			}
			if len(got.WorkflowPlan.ReadOnlyCLICommands) == 0 {
				t.Fatalf("%s should include read-only CLI commands", workflow)
			}
			if len(got.WorkflowPlan.BlockedWriteActions) == 0 || len(got.WorkflowPlan.RequiredApprovalsBeforeLiveExecution) == 0 {
				t.Fatalf("%s should include blocked writes and required approvals", workflow)
			}
			joined := strings.Join(append(append([]string{}, got.WorkflowPlan.ReadOnlyCLICommands...), got.WorkflowPlan.DryRunCommands...), "\n")
			if !strings.Contains(joined, "straddle-pp-cli") {
				t.Fatalf("%s plan should reference CLI commands, got %#v", workflow, got.WorkflowPlan)
			}
			if strings.Contains(strings.ToLower(stdout), "bearer ") || strings.Contains(stdout, "sk_live") || strings.Contains(stdout, "STRADDLE_TOKEN=") {
				t.Fatalf("workflow plan should not emit token literals or bearer examples:\n%s", stdout)
			}
		})
	}
}

func TestWorkflowPlanCommandSuggestionsResolveToRealCommands(t *testing.T) {
	root := newRootCmd(&rootFlags{})
	for _, plan := range workflowPlans() {
		t.Run(plan.Name, func(t *testing.T) {
			for _, suggestion := range workflowPlanCommandSuggestions(plan) {
				path := commandPathFromSuggestion(t, suggestion)
				cmd, _, err := root.Find(path)
				if err != nil {
					t.Fatalf("suggestion %q did not resolve: %v", suggestion, err)
				}
				if cmd == nil {
					t.Fatalf("suggestion %q resolved to nil command", suggestion)
				}
				if !strings.Contains(suggestion, " --help") && cmd.Run == nil && cmd.RunE == nil {
					t.Fatalf("suggestion %q resolved to %q without executable behavior", suggestion, cmd.CommandPath())
				}
			}
		})
	}
}

