func workflowPlanCommandSuggestions(plan workflowPlanWorkflow) []string {
	var suggestions []string
	suggestions = append(suggestions, plan.ReadOnlyCLICommands...)
	suggestions = append(suggestions, plan.DryRunCommands...)
	for _, phase := range plan.Phases {
		for _, step := range phase.Steps {
			suggestions = append(suggestions, step.Commands...)
		}
	}
	return suggestions
}

