func TestWorkflowPlanRejectsDeliverBeforeDelivery(t *testing.T) {
	target := filepath.Join(t.TempDir(), "workflow-plan-delivery.json")
	home := t.TempDir()
	t.Setenv("HOME", home)

	oldArgs := os.Args
	t.Cleanup(func() {
		os.Args = oldArgs
	})
	os.Args = []string{
		"straddle-pp-cli",
		"workflow",
		"plan",
		"--deliver",
		"file:" + target,
		"--profile",
		"missing-profile",
	}

	err := Execute()
	if err == nil {
		t.Fatalf("workflow plan should reject --deliver")
	}
	if !strings.Contains(err.Error(), "workflow plan does not support --deliver") {
		t.Fatalf("error should explain --deliver is unsupported, got %v", err)
	}
	if _, statErr := os.Stat(target); !os.IsNotExist(statErr) {
		t.Fatalf("workflow plan should reject --deliver before writing output, stat err=%v", statErr)
	}
	if _, statErr := os.Stat(filepath.Join(home, ".straddle-pp-cli")); !os.IsNotExist(statErr) {
		t.Fatalf("workflow plan should reject --deliver before loading profile state, stat err=%v", statErr)
	}
}

